/// <summary>
/// Extension of UnitOfMeasureTranslation table
/// </summary>
[ExtensionOf(tableStr(UnitOfMeasureTranslation))]
internal final class NDXUnitOfMeasureTranslation_tbl_Extension
{
}

Method.Source:
/// <summary>
/// Finds or creates UnitOfMeasureTranslation record by Nieda UnitTXT record
/// </summary>
/// <param name = "_record">Niedax UnitTxt record </param>
/// <returns>UnitOfMeasureTranslation record</returns>
static public UnitOfMeasureTranslation findOrCreateByObject(Niedax.Units.UnitTxtRecord _record)
{
    UnitOfMeasureTranslation lUnitOfMeasureTranslation;
    UnitOfMeasureSymbol lUnitOfMeasureSymbol;
    LanguageId languageId;
    UnitOfMeasure lUnitOfMeasure;

    if(_record != null)
    {
        lUnitOfMeasureSymbol = _record.UnitId;
        languageId = _record.LanguageId;

        lUnitOfMeasure = UnitOfMeasure::findBySymbol(lUnitOfMeasureSymbol);

        if(lUnitOfMeasure)
        {

            lUnitOfMeasureTranslation = UnitOfMeasureTranslation::findByTranslation(lUnitOfMeasure.RecId, languageId, true);

            if(!lUnitOfMeasureTranslation)
            {
                lUnitOfMeasureTranslation.UnitOfMeasure = lUnitOfMeasure.RecId;
                lUnitOfMeasureTranslation.insert();
            }

            lUnitOfMeasureTranslation.LanguageId = _record.LanguageId;
            lUnitOfMeasureTranslation.Description = _record.UnitIDTxt;

            ttsbegin;
            lUnitOfMeasureTranslation.update();
            ttscommit;
        }
    }
    return lUnitOfMeasureTranslation;
}
